import { PaletteOptions } from "@mui/material/styles";

// ESKOM OFFICIAL BRAND COLORS
// Research from Eskom brand guidelines:
// Primary: Blue #003DA5
// Secondary: Yellow #FFD100
// Supporting: Grey #58595B

const palette: PaletteOptions = {
  mode: "light",

  primary: {
    main: "#003DA5", // Eskom Corporate Blue
    light: "#3366C2",
    dark: "#002B75",
    contrastText: "#FFFFFF",
  },

  secondary: {
    main: "#FFD100", // Eskom Yellow
    light: "#FFE14D",
    dark: "#CCA700",
    contrastText: "#003DA5",
  },

  success: {
    main: "#4CAF50",
    light: "#81C784",
    dark: "#388E3C",
  },

  warning: {
    main: "#FF9800",
    light: "#FFB74D",
    dark: "#F57C00",
  },

  error: {
    main: "#F44336",
    light: "#E57373",
    dark: "#D32F2F",
  },

  info: {
    main: "#003DA5",
    light: "#3366C2",
    dark: "#002B75",
  },

  background: {
    default: "#F8F9FA",
    paper: "#FFFFFF",
  },

  text: {
    primary: "#1A1A1A",
    secondary: "#58595B", // Eskom Grey
    disabled: "rgba(0, 0, 0, 0.38)",
  },

  divider: "#E0E0E0",

  grey: {
    50: "#FAFAFA",
    100: "#F5F5F5",
    200: "#EEEEEE",
    300: "#E0E0E0",
    400: "#BDBDBD",
    500: "#9E9E9E",
    600: "#757575",
    700: "#616161",
    800: "#424242",
    900: "#212121",
  },
};

export default palette;
